ee:variables.ee:set-variable:
%dw 2.0
output application/java
var errNamespace = error.errorType.namespace default ""
var errIdentifier = error.errorType.identifier default ""
var businessErrors = {
    INVALID_EVENT: { code: "INVALID_INVENTORY_EVENT", httpStatus: 400, status: "REJECTED", category: "INPUT", message: "Required inventory field is missing or invalid." },
    UNKNOWN_MOVEMENT: { code: "UNSUPPORTED_MOVEMENT_TYPE", httpStatus: 400, status: "REJECTED", category: "INPUT", message: "Movement type is not supported." },
    UNKNOWN_REFERENCE: { code: "REFERENCE_NOT_FOUND", httpStatus: 404, status: "REJECTED", category: "MASTER_DATA", message: "SKU or location does not exist or is inactive." },
    NEGATIVE_AVAILABLE: { code: "NEGATIVE_AVAILABLE_QUANTITY", httpStatus: 422, status: "REJECTED", category: "BUSINESS", message: "Available quantity cannot be negative." },
    VERSION_CONFLICT: { code: "VERSION_CONFLICT", httpStatus: 409, status: "CONFLICT", category: "CONCURRENCY", message: "Concurrent inventory update detected." },
    STALE_EVENT: { code: "STALE_EVENT_VERSION", httpStatus: 409, status: "STALE", category: "ORDERING", message: "Event version is not newer than the stored version." },
    DUPLICATE_EVENT: { code: "DUPLICATE_EVENT", httpStatus: 409, status: "DUPLICATE", category: "DUPLICATE", message: "Event ID has already been processed." }
}
var unavailableIds = ["CONNECTIVITY", "RETRY_EXHAUSTED", "TIMEOUT", "SERVICE_UNAVAILABLE", "GATEWAY_TIMEOUT"]
var businessDefault = { code: "INVALID_INVENTORY_EVENT", httpStatus: 400, status: "REJECTED", category: "BUSINESS", message: "Invalid inventory event." }
var unavailableInfo = { code: "SERVICE_UNAVAILABLE", httpStatus: 503, status: "RETRY_PENDING", category: "TECHNICAL", message: "A required system is temporarily unavailable. The event was sent for investigation.", retryable: true, level: "ERROR" }
var unexpectedInfo = { code: "INTERNAL_SERVER_ERROR", httpStatus: 500, status: "FAILED", category: "TECHNICAL", message: "Unexpected inventory processing error.", retryable: false, level: "ERROR" }
---
if (errNamespace == "INVENTORY") ((businessErrors[errIdentifier] default businessDefault) ++ { retryable: false, level: "WARN" }) else (if (unavailableIds contains errIdentifier) unavailableInfo else unexpectedInfo)
